// Fills the website prompt with this lead's data and asks Claude for one complete HTML file.
const s = $json;
let found = {};
try { found = typeof s.enrichment === 'string' ? JSON.parse(s.enrichment || '{}') : (s.enrichment || {}); } catch (e) {}
const business = JSON.stringify({
  name: s.name, category: s.category, address: s.address, city: s.city, phone: s.phone || found.phone || null,
  email: s.email || found.email || null, existing_website: s.website || null, ...found }, null, 2);
const content = `${s.website_prompt}

---
Business information (the only facts you may use about this business; fill the [bracketed] parts of the brief from it):
${business}

Technical rules for this page:
- Return ONE complete, self-contained HTML file: all CSS and JavaScript inline. Google Fonts is the only allowed external stylesheet.
- Use the photo_urls above for imagery when given; otherwise use inline SVG illustrations. No stock-photo links.
- "Pages" are sections of this one page, linked from the header navigation.
- Testimonials: use the real reviews above (top_reviews, rating, review_count). If there are none, show clearly marked placeholder testimonials.
- Map: embed https://maps.google.com/maps?q=<url-encoded address>&output=embed in an iframe.
- The contact form has no backend yet: on submit, show a thank-you message.
- Add <meta name="robots" content="noindex"> and a small footer line: "Free concept preview for ${s.name}".
- Reply with only the HTML, starting with <!doctype html>.`;
return { json: { claude_body: {
  model: s.claude_model, max_tokens: s.max_tokens, stream: true,
  thinking: { type: 'adaptive' }, output_config: { effort: s.effort },
  messages: [{ role: 'user', content }] } } };

// Plug-in output: the lead as it came in, plus landing_html. If no page came back: status 'error' + notes.
const leads = $('Lead in').all().map(i => i.json);
return $input.all().map((item, i) => {
  const r = item.json, lead = leads[i];
  // Claude streams its answer (needed for long pages): join the text pieces back together.
  let text = '', stop = r.stop_reason || '', err = r.error ? (r.error.message || JSON.stringify(r.error)) : '';
  if (typeof r.data === 'string') {
    for (const line of r.data.split('\n')) {
      if (!line.startsWith('data:')) continue;
      let ev; try { ev = JSON.parse(line.slice(5)); } catch (e) { continue; }
      if (ev.type === 'content_block_delta' && ev.delta?.type === 'text_delta') text += ev.delta.text;
      else if (ev.type === 'message_delta') stop = ev.delta?.stop_reason || stop;
      else if (ev.type === 'error') err = ev.error?.message || 'stream error';
    }
  } else {
    text = (r.content || []).filter(b => b.type === 'text').map(b => b.text).join('');
  }
  const start = text.search(/<!doctype html|<html/i), end = text.toLowerCase().lastIndexOf('</html>');
  if (err || start < 0 || end < start) {
    const why = err || `no HTML in reply (stop_reason: ${stop || 'unknown'})`;
    return { json: { ...lead, landing_html: '', status: 'error', notes: `Website: ${why}`.slice(0, 500) } };
  }
  return { json: { ...lead, landing_html: text.slice(start, end + 7) } };
});
